'use strict';
const ANALYSES = [
 {id:'fornecedor',name:'Preparar reunião com fornecedor',category:'Fornecimento',short:'Chegue à conversa com fatos, desvios e perguntas bem fundamentadas.',result:'Uma pauta de revisão com histórico do fornecedor, evidências e perguntas para os pontos em aberto.',keys:['ready','docs','quantity','condition'],entity:'supplier',steps:['Identifique fornecedor/exportador, operações e compromisso de prontidão no período.','Separe prontidão, documentação, quantidade recebida e condição da mercadoria.','Compare períodos com denominadores e variantes explícitos; destaque registros ausentes.','Prepare perguntas a partir dos casos. Não atribua atraso de transporte ao fornecedor sem apuração.'],questions:['Quais compromissos de prontidão precisam ser revistos?','As correções documentais têm causa e efeito registrados?','O que falta confirmar nos recebimentos?']},
 {id:'atraso',name:'Investigar um atraso',category:'Prazos',short:'Reconstrua o percurso e descubra em quais etapas o prazo se desviou.',result:'Uma cronologia do caso, comparação do combinado com o realizado e perguntas de apuração.',keys:['ready','collect','port','final','stages','cause'],steps:['Localize o caso e confira identidade, período e fontes dos marcos.','Separe compromisso original, previsão revisada e evento realizado.','Compare cada trecho com sua própria referência e mantenha etapas abertas fora dos tempos concluídos.','Mostre evidências e lacunas. Excesso de prazo localiza o desvio, mas não determina sua causa.'],questions:['Qual foi o primeiro marco com desvio documentado?','Houve revisão da previsão e qual compromisso foi preservado?','Que evidência ainda falta para apurar a causa?']},
 {id:'rotas',name:'Comparar rotas',category:'Transporte',short:'Compare os percursos considerando serviço, amostra e cobertura.',result:'Uma comparação por corredor e variante, com os limites que impedem uma recomendação conclusiva.',keys:['route','stages','port','final','freight'],steps:['Agrupe operações por corredor, variante, modal e equipamento.','Confira equivalência de coleta/destino, período, escopo e moeda antes de comparar.','Apresente tamanho da amostra, tempos realizados e frete contratado separadamente.','Declare diferenças de serviço e dados ausentes. Não recomende trocar de rota apenas pela menor média.'],questions:['As alternativas atendem à mesma necessidade e aos mesmos locais?','Os serviços e equipamentos são comparáveis?','Há oferta atual que sustente a escolha?']},
 {id:'agente',name:'Revisar desempenho do agente',category:'Parceiros',short:'Conecte contratação, execução e conferência financeira.',result:'Uma revisão do relacionamento, com resultados financeiros e de prazo independentes.',keys:['freight','port','final','audit','cause'],entity:'agent',steps:['Ligue cada operação ao agente e à versão da proposta efetivamente aceita.','Compare condições contratadas e eventos, preservando o compromisso original.','Confronte fatura e contrato por linha, moeda e escopo quando houver conferência.','Separe divergência, contestação e recuperação comprovada. Preferência cadastral não é desempenho.'],questions:['Quais diferenças de cobrança estão fundamentadas?','Quais compromissos tiveram desvio de prazo?','Que esclarecimentos ainda dependem do agente?']},
 {id:'mensal',name:'Preparar revisão mensal',category:'Gestão',short:'Organize os resultados do período e os pontos que merecem atenção.',result:'Um rascunho de revisão com indicadores, casos explicativos, lacunas e pauta para a gestão.',keys:['ready','port','final','freight','cargo'],steps:['Confirme empresa, período, filtros e unidade de análise.','Resuma desempenho usando as mesmas métricas e denominadores das fichas.','Identifique recorrências descritivas por parceiro e etapa, sem presumir causalidade.','Apresente uma pauta fundamentada. Não estime impacto em estoque, produção, vendas ou savings sem fonte.'],questions:['Quais desvios merecem aprofundamento?','Em quais indicadores a cobertura limita a leitura?','Que dados precisam entrar na próxima revisão?']}
];
const assistantDrafts=new Map();
let assistantProvider='Claude';
function assistantNav(current='biblioteca'){return tabs('assistentes',[['biblioteca','Biblioteca'],['conectar','Conectar sua IA']],current);}
function assistantHref(a){const changes={};if(a.entity&&!params.get(a.entity))changes[a.entity]=a.entity==='supplier'?'east':'alpha';return url('assistentes/'+a.id+'/resumo',changes);}
function assistantContextText(){const r=periodRange();return `Empresa: Aurora Indústria (demonstração).\nPeríodo: ${r.valid?fullDate(r.start)+' a '+fullDate(r.end):'intervalo inválido; definir antes de analisar'}.\nCritério do período: compromisso original de prontidão. Corte: ${fullDate(D.cutoff)}.\nFornecedor: ${params.get('supplier')?company(params.get('supplier')).name:'todos no recorte'}.\nAgente: ${params.get('agent')?agent(params.get('agent')).name:'todos no recorte'}.\nRota: ${params.get('route')?routeName(route(params.get('route'))):'todas no recorte'}.\nVariante: ${params.get('variant')==='conexao'?'via Singapura':params.get('variant')==='direto'?'direta':'todas no recorte'}.`;}
function assistantCase(){return scope.find(o=>o.id===params.get('case'))||scope[0];}
function assistantPrompt(a){return `${a.name}\n\n${assistantContextText()}${a.id==='atraso'?'\nCaso: '+(assistantCase()?.id||'nenhum caso no recorte')+'.':''}\n\nObjetivo\n${a.result}\n\nMétodo\n${a.steps.map((s,i)=>(i+1)+'. '+s).join('\n')}\n\nRegras de evidência\nUse somente dados aos quais meu usuário e minha empresa têm acesso. Use as definições das métricas do Centrix; não invente valores, documentos, datas ou responsabilidades. Para cada conclusão, mostre período, fonte, cobertura e IDs dos casos que a explicam. Se faltar dado ou conexão, explique o que falta antes de concluir. Dados ausentes não contam como sucesso.\n\nFormato de saída\nResumo factual; tabela de resultados e cobertura; casos explicativos; lacunas; perguntas para a revisão.\n\nContexto desta prévia\nNomes, IDs e operações são fictícios. Este prompt não leva os dados da prévia nem estabelece uma conexão MCP. Para uso real, substitua o contexto e consulte fontes autorizadas. Não gere resultados comerciais reais com os exemplos.`;}
function assistantSkill(a){return `---\nname: centrix-${a.id}\ndescription: ${a.result}\nversion: 0.1.0\nstatus: draft\n---\n\n# ${a.name}\n\nMétodo proposto para revisão; sem execução automática. Compatibilidade com cada cliente de IA ainda precisa ser validada.\n\n## Entradas\nEmpresa e usuário autorizados; período e seu critério; filtros de fornecedor, agente, rota e variante. ${a.id==='atraso'?'Identificador do caso. ':''}Confirmar contexto antes de consultar.\n\n## Fontes e requisitos\n${a.keys.map(k=>'- '+DATA_HELP[k][0]+': '+DATA_HELP[k][2]).join('\n')}\n\n## Procedimento\n${a.steps.map((s,i)=>(i+1)+'. '+s).join('\n')}\n\n## Saída\nResumo factual, tabela com numeradores/denominadores, fontes e casos rastreáveis, lacunas e perguntas de apuração.\n\n## Limites\nReutilize as definições do Centrix. Separe original/previsto/realizado e porto/destino final. Não invente dados, scores, causalidade, impacto financeiro ou responsabilidade. Não conte ausência como sucesso. Não envie mensagens nem altere operações. Se fontes ou permissões forem insuficientes, indique o que falta. Identifique explicitamente dados demonstrativos.\n`;} 
function assistantCards(q=''){const list=ANALYSES.filter(a=>(a.name+' '+a.short+' '+a.category).toLocaleLowerCase('pt-BR').includes(q.toLocaleLowerCase('pt-BR')));return list.length?list.map((a,i)=>`<article class="panel assistant-card"><div class="assistant-card-top"><span class="overline">${a.category}</span><span class="assistant-number">0${ANALYSES.indexOf(a)+1}</span></div><h2><a href="${esc(assistantHref(a))}">${a.name}</a></h2><p>${a.short}</p><div class="assistant-card-meta">Skill + prompt · v0.1 <span>Exemplo demonstrativo</span></div><a class="link" href="${esc(assistantHref(a))}">Explorar análise <span aria-hidden="true">→</span></a></article>`).join(''):'<div class="panel pad"><h2>Nenhuma análise encontrada</h2><p class="muted spaced">Tente fornecedor, atraso, rotas, agente ou revisão.</p></div>';}
function assistantsLibrary(){scope=filtered();return heading('Assistentes','Métodos prontos para explorar seus dados e preparar decisões.')+assistantNav()+`<div class="assistant-intro"><div><h2>Escolha uma análise e ajuste o contexto.</h2><p>Explore o exemplo, copie o prompt ou baixe a skill com o método completo.</p></div><div class="assistant-intro-status"><span class="pill">MCP planejado</span><small>Prompts e skills disponíveis para explorar.</small></div></div><div class="search spaced"><input id="assistant-search" type="search" aria-label="Buscar análise" placeholder="Buscar uma análise"><small>5 análises · contexto e fontes explícitos</small></div><div class="assistant-grid" id="assistant-results">${assistantCards()}</div><div class="note spaced">Os exemplos usam as mesmas operações das fichas. Uma conexão futura permitirá consultar dados autorizados; ela não cria os registros que ainda faltam.</div>`;}
function assistantSources(a){return a.keys.map(k=>`<div class="assistant-source"><div><b>${DATA_HELP[k][0]}</b>${dataHelp(k)}<small>${DATA_HELP[k][1]}</small></div><span class="pill">A confirmar</span></div>`).join('');}
function assistantExample(a){if(!scope.length)return `<div class="note">Sem operações neste recorte. Ajuste o período ou os filtros para ver um exemplo com evidências.</div>`;let body='';
 if(a.id==='atraso'){const o=assistantCase();scope=[o];body=`<p class="muted">${link('casos/'+o.id,o.id+' · '+o.po)} · ${company(o.supplier).name}</p>${operationsTable([o])}<div class="spaced">${stagePanel([o])}</div>`;}
 else if(a.id==='rotas'){body=table(['Corredor / variante','Base','Trânsito realizado','Frete contratado'],D.routes.flatMap(r=>['direto','conexao'].map(v=>{const ops=scope.filter(o=>o.route===r.id&&o.variant===v);if(!ops.length)return '';const done=ops.filter(o=>o.depart&&o.arrive),days=done.map(o=>D.days(o.depart,o.arrive)),f=D.metric('freight',ops);return `<tr><td>${link('rotas/'+r.id+'/resumo',routeName(r),{variant:v})}<small>${v==='direto'?'Direta':'Via Singapura'} · ${r.equipment}</small></td><td>${ops.length} operações</td><td>${days.length?Math.min(...days)+'–'+Math.max(...days)+' d':'Sem par de eventos'}<small>${done.length}/${ops.length} com partida e chegada</small></td><td>${f.eligible.length?money(f.total):'—'}<small>Total internacional · USD · ${f.eligible.length}/${ops.length}</small></td></tr>`;})).join(''))+'<p class="muted spaced">Serviços, equipamentos e locais diferem. Estes totais e intervalos não sustentam uma classificação de melhor rota; falta confirmar equivalência e condições atuais.</p>';}
 else {const keys=a.id==='fornecedor'?['ready','docs','quantity','condition']:a.id==='agente'?['freight','port','final','audit']:['ready','port','final','freight'];body=metrics(keys,scope)+`<p class="muted">${scope.length} operações no recorte. Os indicadores abrem seus casos e denominadores. Desvios de transporte não determinam responsabilidade.</p><div class="spaced">${a.id==='mensal'?stagePanel(scope):operationsTable(scope)}</div>`;}
 return `<div class="note">Exemplo demonstrativo calculado na prévia, sem execução de IA. ${esc(periodText())}.</div><div class="spaced">${body}</div><div class="spaced">${panel('Perguntas para a revisão','Pauta sugerida pelo método; ainda sem resposta apurada.',`<ol class="assistant-steps">${a.questions.map(q=>`<li>${q}</li>`).join('')}</ol>`)}</div>`;}
function assistantDetail(id,tab='resumo'){const a=ANALYSES.find(x=>x.id===id);if(!a)return empty('Análise não encontrada');scope=filtered();const base='assistentes/'+id;const draftKey=url(base+'/prompt');let body='';
 const selector=a.entity?`<label>${a.entity==='supplier'?'Fornecedor':'Agente'} <select data-filter="${a.entity}" aria-label="${a.entity==='supplier'?'Fornecedor da análise':'Agente da análise'}"><option value="">Todos no recorte</option>${(a.entity==='supplier'?D.companies:D.agents).map(x=>`<option value="${x.id}" ${params.get(a.entity)===x.id?'selected':''}>${x.name}</option>`).join('')}</select></label>`:a.id==='atraso'?`<label>Caso <select id="assistant-case" aria-label="Caso da análise">${scope.length?scope.map(o=>`<option value="${o.id}" ${assistantCase()?.id===o.id?'selected':''}>${o.id} · ${o.po}</option>`).join(''):'<option>Nenhum caso no recorte</option>'}</select></label>`:'';
 if(tab==='resumo')body=`<div class="assistant-detail-grid">${panel('O que você recebe',a.result,`<ol class="assistant-steps">${a.steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="pad actions">${link(base+'/prompt','Preparar prompt',{},'button')}${link(base+'/exemplo','Ver exemplo com esta base',{},'button secondary')}</div>`)}${panel('Dados necessários','Passe pelo indicador para entender o que falta confirmar.',assistantSources(a))}</div>`;
 else if(tab==='prompt'){const draft=assistantDrafts.get(draftKey)||assistantPrompt(a);body=`<div class="assistant-detail-grid"><section class="panel pad"><div class="assistant-prompt-head"><div><h2>Seu prompt</h2><p class="muted">Contexto preenchido. Ajuste o pedido antes de copiar.</p></div><span class="pill">Editável</span></div><label class="sr-only" for="assistant-prompt">Prompt da análise</label><textarea id="assistant-prompt" data-draft-key="${esc(draftKey)}" spellcheck="false">${esc(draft)}</textarea><div class="actions spaced">${action('Copiar prompt','assistant-copy',id,'button')}${action('Restaurar modelo','assistant-reset',id,'text-button')}</div><small class="spaced">Copiar leva apenas este texto. Nenhuma consulta ou envio à IA é realizado.</small></section><div class="stack">${panel('Skill de análise','O método reutilizável, com fontes, passos e limites.',`<div class="pad"><p>Versão 0.1 · Rascunho para revisão</p><p class="muted spaced">Baixe o Markdown para revisar e adaptar ao seu ambiente. Compatibilidade de instalação ainda não validada.</p><div class="actions spaced">${action('Ver skill','assistant-skill',id)}${action('Baixar .md','assistant-download',id,'text-button')}</div></div>`)}${panel('Usar com seus dados','A conexão MCP está planejada.',`<div class="pad"><p class="muted">Para uso real, substitua o contexto demonstrativo e conecte uma fonte autorizada. Ter um prompt não significa ter acesso aos dados.</p><div class="spaced">${link('assistentes/conectar','Conhecer a conexão')}</div></div>`)}</div></div>`;}
 else if(tab==='exemplo')body=assistantExample(a);else body=empty('Aba não encontrada');
 return heading(a.name,a.short,'',link('assistentes/biblioteca','‹ Biblioteca',{},'back'))+`<div class="assistant-context">${selector}<small>${scope.length} operações demonstrativas · ${esc(periodText())}</small></div>`+tabs(base,[['resumo','Como funciona'],['prompt','Skill e prompt'],['exemplo','Exemplo']],tab)+body;
}
function assistantConnection(){return heading('Conectar sua IA','Leve o contexto do Centrix para a ferramenta em que você já trabalha.')+assistantNav('conectar')+`<div class="assistant-connection-grid"><section class="panel pad"><div class="assistant-step-title"><span>1</span><h2>Escolha sua IA</h2></div><p class="muted">Explore como será a conexão. Nenhum acesso será criado nesta prévia.</p><fieldset class="assistant-providers"><legend class="sr-only">Sua ferramenta de IA</legend>${['Claude','ChatGPT','Outra IA'].map(n=>`<label><input type="radio" name="assistant-provider" value="${n}" ${n===assistantProvider?'checked':''}><b>${n}</b><small>${n==='Outra IA'?'Cliente compatível com MCP':'Compatibilidade a validar'}</small></label>`).join('')}</fieldset><div class="assistant-step-title spaced"><span>2</span><h2>Confira o acesso previsto</h2></div><div class="assistant-permissions"><p><b>Empresa:</b> Aurora Indústria · exemplo</p><p><b>Consultar:</b> operações, parceiros, métricas e evidências disponíveis.</p><p><b>Preparar:</b> análises e rascunhos de revisão.</p><p><b>Alterações e envios:</b> fora deste primeiro escopo.</p></div><small>A conta autenticada deverá definir a empresa e as permissões; os filtros da tela só definem o recorte da análise.</small><div class="assistant-step-title spaced"><span>3</span><h2>Comece por uma análise</h2></div><p class="muted">Com a conexão validada, use uma análise da biblioteca como ponto de partida.</p><div class="actions spaced">${action('Ver configuração prevista','assistant-connection','','button secondary')}${link('assistentes/biblioteca','Explorar biblioteca',{},'button')}</div></section><div class="stack">${panel('Situação da conexão','Nenhuma IA conectada.',`<div class="pad"><span class="pill">Planejado</span><p class="spaced">O servidor MCP, a autenticação e o acesso por empresa ainda precisam ser implementados e verificados.</p><small class="spaced">Não há endereço de servidor ou credenciais para cadastrar nesta prévia.</small></div>`)}${panel('Uma base, diferentes perguntas','As mesmas definições das fichas.',`<div class="pad"><p class="muted">A resposta deve preservar período, fonte, cobertura e casos. O MCP não preenche documentos ou eventos ausentes.</p><p class="spaced">Skills orientam o método. Prompts formulam o pedido. A conexão permite consultar dados autorizados.</p></div>`)}</div></div>`;}
function assistantsView(id,tab){return !id||id==='biblioteca'?assistantsLibrary():id==='conectar'?assistantConnection():assistantDetail(id,tab);}
function assistantDownload(a){const blob=new Blob([assistantSkill(a)],{type:'text/markdown;charset=utf-8'}),href=URL.createObjectURL(blob),anchor=document.createElement('a');anchor.href=href;anchor.download='centrix-'+a.id+'-SKILL.md';anchor.click();setTimeout(()=>URL.revokeObjectURL(href),1000);toast('Skill em Markdown baixada. Instalação não realizada.');}
document.addEventListener('input',e=>{if(e.target.id==='assistant-search')$('#assistant-results').innerHTML=assistantCards(e.target.value);if(e.target.id==='assistant-prompt')assistantDrafts.set(e.target.dataset.draftKey,e.target.value);});
document.addEventListener('change',e=>{if(e.target.id==='assistant-case')location.hash=url(pagePath,{case:e.target.value});if(e.target.name==='assistant-provider')assistantProvider=e.target.value;});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action^="assistant-"]');if(!b)return;const a=ANALYSES.find(x=>x.id===b.dataset.id);switch(b.dataset.action){case 'assistant-copy':try{await navigator.clipboard.writeText($('#assistant-prompt').value);toast('Prompt copiado. Nenhum dado consultado ou enviado à IA.');}catch{$('#assistant-prompt').focus();$('#assistant-prompt').select();toast('Selecione Copiar no seu dispositivo para copiar o texto destacado.');}break;case 'assistant-reset':assistantDrafts.delete($('#assistant-prompt').dataset.draftKey);$('#assistant-prompt').value=assistantPrompt(a);toast('Modelo restaurado com o recorte atual.');break;case 'assistant-download':assistantDownload(a);break;case 'assistant-skill':openDrawer('Skill · '+a.name,'Versão 0.1 · Método proposto',`<pre class="assistant-skill">${esc(assistantSkill(a))}</pre>${action('Baixar .md','assistant-download',a.id)}`);break;case 'assistant-connection':openDrawer('Conexão com '+assistantProvider,'Configuração prevista · nenhum acesso criado',`<ol class="assistant-steps"><li>Quando disponível, autorizar sua conta Centrix no cliente de IA escolhido.</li><li>Conferir a empresa e as capacidades de consulta permitidas.</li><li>Validar uma consulta e suas fontes antes de usar a biblioteca.</li><li>Consultar ou revogar o acesso na administração de conexões, ainda planejada.</li></ol><div class="note">A conexão com ${assistantProvider} não foi testada. Servidor, autenticação e permissões ainda não estão disponíveis. Nenhuma autorização, instalação ou envio foi iniciado.</div>`);break;}});
